from lib import *
S = SS('w69')
steps = [
    step("地址与别名记录的 RDATA 原始字节。A 记录的 RDATA 就是 4 个字节:ac 42 93 f3 = 172.66.147.243,68 14 17 9a = 104.20.23.154(example.com 有 2 条,TTL 293)。AAAA 的 RDATA 是 16 个字节:26 06 47 00 00 10 00 … 68 14 17 9a = 2606:4700:10::6814:179a,以及另一条 …ac42:93f3(报文 85 字节)。CNAME 的 RDATA 是一个名字:www.github.com 的 CNAME 只有 2 个字节 c0 10——不是名字本身,而是指向报文偏移 16 的压缩指针,解出来是 github.com(TTL 3600)。以上与 8.8.8.8 的回答完全一致,没有发现被篡改的迹象。", t=tl(S(1)), mark=lidx(S(1), 'ac 42 93 f3', 'c0 10', '26 06 47 00'), done=lidx(S(1), '与 8.8.8.8 比较', '解读:IPv4', '解读:IPv6', '解读:名字 github.com'), kv=KV([['A', '4 字节 IPv4'], ['AAAA', '16 字节 IPv6'], ['CNAME', '一个域名(这里是压缩指针 c0 10)']], ['CNAME'])),
    step("MX:RDATA = 2 字节优先级 + 一个域名(数值小的优先)。gmail.com 有 5 条 MX:优先级 5 的 gmail-smtp-in.l.google.com,和 20 / 30 / 40 的 alt2 / alt3 / alt4.gmail-smtp-in.l.google.com;后几条只有 9 个字节,因为名字后半截 gmail-smtp-in.l.google.com 用 c0 29 指针指回前面。注意:与 8.8.8.8 比较,这一条回答“不完全一致”(条数都是 5,但内容有差别),我没有查具体差在哪。NS:example.com 的两条 NS(hera.ns.cloudflare.com、elliott.ns.cloudflare.com),TTL 82536 秒(约 23 小时)。SOA:主名字服务器 elliott.ns.cloudflare.com,管理员邮箱 dns.cloudflare.com(第一个点代表 @),序列号 2416374680,刷新 10000 秒,重试 2400 秒,过期 604800 秒,最小 TTL 1800 秒;最后这个字段就是上一篇里负缓存的时间。", t=tl(S(2)), mark=lidx(S(2), '回答不完全一致', '解读:主名字服务器'), done=lidx(S(2), '优先级 5,邮件服务器', '解读:名字 hera', '解读:名字 elliott'), kv=KV([['MX', '2 字节优先级 + 名字'], ['NS', '一个名字'], ['SOA', '主服务器、邮箱、序列号、刷新 / 重试 / 过期 / 最小 TTL']], ['SOA'])),
    step("TXT:RDATA 是一串“1 字节长度 + 内容”的字符串(每个最多 255 字节)。gmail.com 有 4 条 TXT,其中一条是 SPF:1f 之后是 31 字节的 \"v=spf1 redirect=_spf.google.com\"(1f 就是长度 31),RDLENGTH 32;另外还有第三方的验证串,它们都放在 TXT 里,这是 TXT 常被拿来做域名所有权验证的原因。SRV:_imaps._tcp.gmail.com 的 RDATA = 优先级 5、权重 0、端口 0x03e1 = 993、目标 imap.gmail.com(服务发现:名字里的 _imaps._tcp 是服务和协议)。CAA:google.com 的 RDATA = flags 0、tag \"issue\"(长度 5)、value \"pki.goog\",意思是只允许 pki.goog 这家 CA 签发证书。三者与 8.8.8.8 的回答均一致。", t=tl(S(3)), mark=lidx(S(3), '1f 76 3d 73 70 66', '00 05 00 00 03 e1', '00 05 69 73 73 75 65'), done=lidx(S(3), '解读:优先级 5,权重 0', '解读:flags 0'), kv=KV([['TXT', '1 字节长度 + 字符串,可多段'], ['SRV', '优先级 / 权重 / 端口 993 / 目标'], ['CAA', 'flags + tag + value']], ['TXT'])),
    step("反向解析:IPv4 地址 a.b.c.d 的反向名字是 d.c.b.a.in-addr.arpa,所以 1.1.1.1 的是 1.1.1.1.in-addr.arpa;IPv6 要把 32 个十六进制位逐位倒过来再加 .ip6.arpa。PTR 的 RDATA 是一个名字:03 \"one\" 03 \"one\" 03 \"one\" 03 \"one\" 00 = one.one.one.one(17 字节),TTL 32。新类型 HTTPS(类型号 65,SVCB 的一种)取 cloudflare.com:SvcPriority 1、TargetName 是 \".\"(表示就是本名字)、后面 58 字节的 SvcParams(其中能看到 alpn 里的 \"h3\" \"h2\" 字符串 02 68 33 02 68 32,还有 IPv4 / IPv6 提示地址)。这类记录让客户端在连接之前就知道服务器支持 HTTP/3 和哪些地址。", t=tl(S(4)), mark=lidx(S(4), '03 6f 6e 65', '00 01 00 00 01 00 06 02 68 33'), done=lidx(S(4), '反向名字的构造', '解读:名字 one.one', '解读:SvcPriority'), kv=KV([['1.1.1.1 的反向名', '1.1.1.1.in-addr.arpa'], ['PTR', 'one.one.one.one'], ['HTTPS(65)', 'SvcPriority + TargetName + SvcParams(alpn=h3,h2 …)']], ['HTTPS(65)'])),
    step("ANY 类型的现状:历史上 ANY(255)能“列出所有记录”,但被拿去做放大攻击,RFC 8482 允许服务器敷衍。实测 1.1.1.1 对 example.com 和 cloudflare.com 的 ANY 都直接回 RCODE 4(NOTIMP,没有实现),回答 0 条,报文只有 29 / 32 字节——查询 29 字节,响应也一样小,放大倍数几乎是 1。现在想知道一个名字有哪些记录,只能一种类型一种类型地问。本篇用到的类型号:A=1、NS=2、CNAME=5、SOA=6、PTR=12、MX=15、TXT=16、AAAA=28、SRV=33、HTTPS=65、CAA=257。", t=tl(S(5)), mark=lidx(S(5), '问 example.com 的 ANY', '问 cloudflare.com 的 ANY'), done=lidx(S(5), '类型号表'), b=bars([['查询 example.com ANY', 29, '29 字节'], ['响应(NOTIMP)', 29, '29 字节']], 32, mark=[], done=[0, 1]), kv=KV([['ANY 查询', '1.1.1.1 回 NOTIMP(RCODE 4)'], ['响应大小', '29 / 32 字节,几乎无放大'], ['替代', '一种类型一种类型地问']], ['ANY 查询'])),
]
A = mkartw('w69', 69, '网络协议,DNS,资源记录,A,AAAA,CNAME,MX,TXT,SRV,SOA,CAA,PTR,HTTPS,真实验证,动画演示',
    '逐类型取 DNS 记录的原始 RDATA 字节并手工解读:A 4 字节、AAAA 16 字节、CNAME 与 MX 后半截用压缩指针、TXT 带长度前缀、SRV 端口 993、CAA 只允许 pki.goog、PTR 反向名字、HTTPS 记录里的 alpn=h3,h2;ANY 在 1.1.1.1 上直接 NOTIMP。每个答案都和 8.8.8.8 交叉核对。',
    '一个域名下可以挂很多种记录:地址、别名、邮件、委派、文本、服务发现、证书授权……它们在线上各是什么样?这篇对每种常见类型取回原始 RDATA 字节,一字节一字节地对着解读,还看了 ANY 为什么不再可用。每个回答都同时问了 8.8.8.8 来交叉核对。',
    [('4 / 16 字节', 'A 与 AAAA 记录的 RDATA 长度'), ('c0 10', 'www.github.com 的 CNAME 记录的 RDATA:只有 2 字节的压缩指针'), ('NOTIMP', '1.1.1.1 对 ANY 查询的 RCODE(4),响应只有 29 字节')],
    [('地址与别名', '<p>A 是 4 字节,AAAA 是 16 字节,CNAME 是一个域名(可被压缩指针代替)。</p>'),
     ('邮件与委派', '<p>MX = 优先级 + 名字;NS = 名字;SOA 含主服务器、管理员邮箱、序列号和一组计时字段,最后一个字段是负缓存时间。</p>'),
     ('文本与服务', '<p>TXT 是带长度前缀的字符串(SPF 就是一条 TXT);SRV 给出优先级、权重、端口和目标;CAA 限定哪些 CA 可以签发证书。</p>'),
     ('反向与新类型', '<p>PTR 用倒过来的地址加 in-addr.arpa;HTTPS(SVCB)在连接前就给出 alpn 和地址提示。</p>'),
     ('ANY', '<p>被拿来做放大攻击,现在 1.1.1.1 直接回 NOTIMP。</p>')],
    steps,
    [ENV_W + '。向 1.1.1.1 取记录、向 8.8.8.8 交叉核对;RDATA 解读是我按各类型的格式手写的解析器;TXT 里的第三方验证串不在文章里展示;TTL 每次运行不同',
     '没有验证:gmail.com 的 MX 在两个解析器之间“不完全一致”的原因(没有逐条比较);DNSSEC 相关记录(DNSKEY、RRSIG、DS,下一篇有 DNSSEC 专题);DNAME、NAPTR、TLSA、SSHFP 等较少见的类型;SVCB / HTTPS 的 SvcParams 逐个字段的解析(只看到了前几个字节);权威服务器上直接取记录(这里都是经过递归解析器的)'],
    '记录类型')
